function loadState(){plans=[];shopping=[];try{({plans,shopping}=readAccountState(localStorage,activeUserId));showShoppingSources=activeUserId?localStorage.getItem('mise-meal-sources-'+activeUserId)!=='false':true;if(activeUserId)writeAccountState(localStorage,activeUserId,{plans,shopping})}catch(error){console.warn('Could not load local UI data.',error)}}
function saveState(){try{writeAccountState(localStorage,activeUserId,{plans,shopping});return true}catch(error){console.warn('Could not save local UI data.',error);toast('Could not save local planner changes');return false}}
function switchAccount(userId){
 if(activeUserId===userId)return;
 sessionVersion++;$('#recipe-peek')?.remove();clearCatalogue();plannerMonday=dateKey(currentWeek()[0]);activeUserId=userId;loadedUserId=null;
 recipes=[];inventory={};currentRecipe=null;cookStep=0;loadState();
 $('#modal-root').innerHTML='';
 for(const id of ['recipes','inventory','planner','shopping','detail','cooking','profile','catalogue'])$('#'+id+'-view').innerHTML='';
 window.miseProfileStats={recipes:0,ingredients:0};show('home');
}
async function currentUser(){let{data,error}=await supabase.auth.getUser();if(error||!data.user)throw new Error(error?.message||'Please sign in again.');return data.user}
function mapRecipe(row){let items=(row.recipe_ingredients||[]).sort((a,b)=>a.sort_order-b.sort_order);return{id:row.id,name:row.name,cuisine:row.cuisine||row.tags?.[0]||'Other',tags:row.tags||[],prep:row.prep_minutes||0,cook:row.cook_minutes||0,time:row.total_minutes??((row.prep_minutes||0)+(row.cook_minutes||0)),difficulty:row.difficulty||'Easy',rating:Number(row.rating)||0,emoji:row.emoji||'🍽️',imageUrl:row.image_url||'',bg:row.background_color||'#dce8df',servings:Number(row.servings)||1,source:row.source_url||row.source||'Personal recipe',ingredients:items.map(item=>{let name=item.ingredient.canonical_name;categories[name]=item.ingredient.category||'Other';return[name,item.quantity===null?null:Number(item.quantity),item.unit,item.preparation_note||'',item.ingredient.id]}),steps:row.instructions||[]}}
async function loadDatabase(session){
 const userId=session?.user?.id||null;switchAccount(userId);
 if(!userId||loadedUserId===userId)return;
 const version=sessionVersion;loadedUserId=userId;toast('Loading your kitchen…');
 try{
 let[recipeResult,inventoryResult]=await Promise.all([supabase.from('recipes').select('*,recipe_ingredients(quantity,unit,preparation_note,sort_order,ingredient:ingredients(id,canonical_name,category))').order('created_at'),supabase.from('inventory').select('id,quantity,unit,storage_location,low_stock_threshold,ingredient:ingredients(id,canonical_name,category)').order('created_at')]);
 if(version!==sessionVersion)return;
 if(recipeResult.error||inventoryResult.error)throw new Error(recipeResult.error?.message||inventoryResult.error?.message);
 recipes=(recipeResult.data||[]).map(mapRecipe);inventory={};(inventoryResult.data||[]).forEach(row=>{let name=row.ingredient.canonical_name;categories[name]=row.ingredient.category||'Other';inventory[name]={id:row.id,ingredientId:row.ingredient.id,qty:Number(row.quantity),unit:row.unit,threshold:Number(row.low_stock_threshold),location:row.storage_location}});shopping=shopping.map(item=>cleanRecipeSources(item,recipes));saveState();window.miseProfileStats={recipes:recipes.length,ingredients:Object.keys(inventory).length};home();let active=document.querySelector('.view.active')?.id;if(active==='recipes-view')recipesView();if(active==='inventory-view')inventoryView();if(active==='planner-view')plannerView();if(active==='shopping-view')shoppingView();if(active==='profile-view')window.dispatchEvent(new CustomEvent('mise-profile-open'));toast('Kitchen loaded')
 }catch(error){
  if(version!==sessionVersion)return;
  loadedUserId=null;recipes=[];inventory={};home();toast(`Could not load kitchen: ${error.message}`);
 }
}
async function uploadRecipeCover(file,userId){if(!file?.size)return'';let ext=(file.name.split('.').pop()||'jpg').toLowerCase(),path=`${userId}/${crypto.randomUUID()}.${ext}`,uploaded=await supabase.storage.from('recipe-covers').upload(path,file,{contentType:file.type,upsert:false});if(uploaded.error)throw uploaded.error;return supabase.storage.from('recipe-covers').getPublicUrl(path).data.publicUrl}
async function createRecipe(record,coverFile){let user=await currentUser();record.imageUrl=await uploadRecipeCover(coverFile,user.id);let sourceIsUrl=/^https?:\/\//i.test(record.source);let created=await supabase.from('recipes').insert({user_id:user.id,name:record.name,cuisine:record.cuisine,tags:record.tags,total_minutes:record.time,prep_minutes:record.prep,cook_minutes:record.cook,difficulty:record.difficulty,servings:record.servings,instructions:record.steps,rating:record.rating,image_url:record.imageUrl||null,emoji:record.emoji,background_color:record.bg,source:sourceIsUrl?null:(record.source||null),source_url:sourceIsUrl?record.source:null}).select('*').single();if(created.error)throw created.error;try{let links=[];for(let i=0;i<record.ingredients.length;i++){let[name,quantity,unit,note,ingredientId]=record.ingredients[i];if(!ingredientId)throw new Error('Select each ingredient from the catalogue.');links.push({recipe_id:created.data.id,ingredient_id:ingredientId,quantity,unit,preparation_note:note||null,sort_order:i})}let joined=await supabase.from('recipe_ingredients').insert(links);if(joined.error)throw new Error(joined.error.code==='23502'?'Optional amounts need database update 008_optional_recipe_quantities.sql in Supabase.':joined.error.message);return{...record,id:created.data.id}}catch(error){await supabase.from('recipes').delete().eq('id',created.data.id);throw error}}
function recipePayload(record){
 const sourceIsUrl=/^https?:\/\//i.test(record.source);
 return {name:record.name,cuisine:record.cuisine,tags:record.tags,total_minutes:record.time,prep_minutes:record.prep,cook_minutes:record.cook,difficulty:record.difficulty,servings:record.servings,instructions:record.steps,image_url:record.imageUrl||null,source:sourceIsUrl?null:(record.source||null),source_url:sourceIsUrl?record.source:null};
}
async function updateRecipe(id,record,file){
 const user=await currentUser();
 if(file?.size)record.imageUrl=await uploadRecipeCover(file,user.id);
 const {error}=await supabase.rpc('update_recipe',{p_id:id,p_recipe:recipePayload(record),p_ingredients:record.ingredients.map(([,quantity,unit,note,ingredient_id])=>({ingredient_id,quantity,unit,preparation_note:note||null}))});
 if(error)throw new Error(error.code==='23502'?'Optional amounts need database update 008_optional_recipe_quantities.sql in Supabase.':error.code==='PGRST202'?'Recipe editing needs the database update 006_recipe_edit.sql applied in Supabase.':error.message);
 return {...record,id};
}
async function deleteRecipe(id){
 const user=await currentUser(),version=sessionVersion,previousRecipes=recipes;
 const {data,error}=await supabase.from('recipes').delete().eq('id',id).eq('user_id',user.id).select('id');
 if(error)throw error;
 if(!data?.length)throw new Error('Recipe not found or access denied.');
 if(version!==sessionVersion)return false;
 shopping=detachRecipeSources(shopping,id,previousRecipes);recipes=recipes.filter(r=>r.id!==id);plans=plans.filter(p=>p.recipe!==id);
 if(currentRecipe?.id===id)currentRecipe=null;
 const saved=saveState();
 $('#detail-view').innerHTML='';$('#cooking-view').innerHTML='';
 home();show('recipes');
 toast(saved?'Recipe deleted':'Recipe deleted. Plan cleanup could not be saved in this browser.');return true;
}

async function upsertInventory(name,item){if(!item.ingredientId)throw new Error('Select an ingredient from the catalogue.');let user=await currentUser(),ingredient={id:item.ingredientId};let result=await supabase.from('inventory').upsert({user_id:user.id,ingredient_id:ingredient.id,quantity:item.qty,unit:item.unit,storage_location:item.location,low_stock_threshold:item.threshold,updated_at:new Date().toISOString()},{onConflict:'user_id,ingredient_id'}).select('id,ingredient_id').single();if(result.error)throw result.error;return{...item,id:result.data.id,ingredientId:result.data.ingredient_id}}
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],fmt=n=>Number.isInteger(n)?n:n.toFixed(1);
function checks(r,s=r.servings){return recipeChecks(r,inventory,s)}
function availability(r,s){return checks(r,s).filter(needsPurchase).length}
function recipeVisual(recipe){return recipe.imageUrl?`<img src="${escapeHtml(recipe.imageUrl)}" alt="${escapeHtml(recipe.name)}" loading="lazy">`:`<div class="cover-fallback">${icon('utensils')}<span>A favourite in the making.</span></div>`}
function card(r){const missing=availability(r);return `<article class="recipe-card" tabindex="0" role="link" aria-label="Open ${escapeHtml(r.name)}" data-recipe="${escapeHtml(r.id)}"><div class="recipe-image">${recipeVisual(r)}<span class="compat ${missing?'warn':''}">${icon(missing?'bag':'check')}${missing?`Missing ${missing}`:'Ready to cook'}</span></div><div class="card-body"><div class="card-copy"><span class="tag">${escapeHtml(r.tags[0]||r.cuisine)}</span><h3>${escapeHtml(r.name)}</h3><div class="card-meta"><span>${icon('clock')}${r.time} min</span><span>·</span><span>${escapeHtml(r.difficulty)}</span></div></div><button class="round-btn" data-open-recipe="${escapeHtml(r.id)}" aria-label="Open ${escapeHtml(r.name)}">${icon('arrow')}</button></div></article>`}
function home(){
 const now=new Date(),ready=recipes.filter(r=>!availability(r)),pick=ready[0]||recipes[0];
 $('#today-label').textContent=new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'}).format(now);
 $('#kitchen-summary').textContent=kitchenSummary(recipes.length,ready.length);
 $('#home-recipes-title').textContent='Your little black cookbook';
 $('#home-recipes').innerHTML=[...ready,...recipes.filter(recipe=>!ready.includes(recipe))].slice(0,3).map(card).join('')||`<div class="empty-state"><h3>Your next favourite starts here.</h3><p>Add a recipe, then make it yours.</p><button class="primary-btn" data-action="add-recipe">${icon('plus')}Add your first recipe</button></div>`;
 const target=$('#home-pick');
 target.innerHTML=pick?`<div class="pick-photo">${recipeVisual(pick)}<span class="compat">${icon(availability(pick)?'book':'check')}${availability(pick)?'From your cookbook':'Ready to cook'}</span></div><div class="pick-copy"><p class="eyebrow">${ready.length?'Tonight, sorted.':'One for the rotation.'}</p><h2>${escapeHtml(pick.name)}</h2><p>${pick.time} min · ${escapeHtml(pick.difficulty)} · ${pick.servings} servings</p><div class="pick-bottom"><span>Good taste. All in one place.</span><button class="primary-btn" data-open-recipe="${escapeHtml(pick.id)}">View recipe ${icon('arrow')}</button></div></div>`:`<div class="empty-pick">${icon('book')}<h2>Good taste.<br>All in one place.</h2><p>Your recipes, your ingredients, your kind of cooking.</p><button class="primary-btn" data-action="add-recipe">Start your collection ${icon('plus')}</button></div>`;
 const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
 const thisWeek=currentWeek(now).map(dateKey);
 const menu=plans.filter(plan=>thisWeek.includes(plan.date)).map(plan=>({plan,recipe:recipes.find(r=>r.id===plan.recipe)})).filter(item=>item.recipe).sort((a,b)=>a.plan.date.localeCompare(b.plan.date));
 const today=new Intl.DateTimeFormat('en',{weekday:'long'}).format(now);
 $('#home-meals').innerHTML=menu.slice(0,3).map(({plan,recipe})=>`<button class="mini-meal ${plan.day===today?'today':''}" data-open-recipe="${escapeHtml(recipe.id)}"><span class="day">${escapeHtml(plan.day.slice(0,3).toUpperCase())}</span><span class="meal-copy"><strong>${escapeHtml(recipe.name)}</strong><small>${escapeHtml(plan.slot)} · ${plan.servings} servings</small></span>${recipe.imageUrl?`<img src="${escapeHtml(recipe.imageUrl)}" alt="" loading="lazy">`:icon('utensils')}</button>`).join('')||'<p class="menu-empty">Your week is wide open.<br>Put something lovely on the menu.</p>';
 const low=Object.entries(inventory).filter(([,item])=>item.qty<=item.threshold);
 $('#low-count').textContent=low.length;
 $('#low-stock-list').innerHTML=low.slice(0,3).map(([name,item])=>`<div class="stock-row"><span class="stock-icon">${icons[categories[name]]||icon('box')}</span><div><strong>${escapeHtml(name)}</strong><small>${item.qty===0?'Out of stock':`${item.qty} ${escapeHtml(item.unit)} left`}</small></div></div>`).join('')||'<p class="menu-empty">All stocked up. Lovely.</p>';
 $('.low-panel .full-soft-btn').disabled=!low.length;
}

function recipesView(){$('#recipes-view').innerHTML=`<div class="page-head"><div><p class="eyebrow">YOUR LITTLE BLACK COOKBOOK</p><h1>Recipes</h1><p>${recipes.length} recipes · ${recipes.filter(r=>!availability(r)).length} ready to cook</p></div><button class="primary-btn" data-action="add-recipe">＋ Add recipe</button></div><div class="toolbar"><label class="search">${icon('search')} <input id="recipe-search" placeholder="Search recipes or ingredients…"></label><button class="filter active" data-filter="all">All</button><button class="filter" data-filter="ready">Ready now</button><button class="filter" data-filter="Easy">Easy</button></div><div class="recipe-grid" id="all-recipes">${recipes.map(card).join('')}</div>`}
function invRows(rows){return rows.map(([n,v])=>{let st=v.qty===0?'Out of stock':v.qty<=v.threshold?'Low stock':'In stock';return `<tr data-location-row="${v.location}"><td><span class="food-icon">${icons[categories[n]]||icon('box')}</span><strong>${n}</strong></td><td><span class="status ${st==='In stock'?'good':st==='Low stock'?'low':'out'}">${st}</span></td><td><div class="qty-control"><button data-qty="-" data-name="${n}">−</button><b>${v.qty} ${v.unit==='piece'&&v.qty!==1?'pieces':v.unit}</b><button data-qty="+" data-name="${n}">＋</button></div></td><td>${v.location}</td><td>${categories[n]||'Other'}</td></tr>`}).join('')}
function inventoryView(){let rows=Object.entries(inventory);$('#inventory-view').innerHTML=`<div class="page-head"><div><p class="eyebrow">AT HOME</p><h1>Inventory</h1><p>${rows.length} ingredients across fridge, freezer and pantry</p></div><div class="detail-actions"><button class="secondary-btn" data-view="catalogue">Manage ingredients</button><button class="primary-btn" data-action="add-inventory">＋ Add ingredient</button></div></div><div class="stat-grid"><div class="stat"><b>${rows.filter(([,v])=>v.qty>v.threshold).length}</b><span>In stock</span></div><div class="stat amber"><b>${rows.filter(([,v])=>v.qty>0&&v.qty<=v.threshold).length}</b><span>Running low</span></div><div class="stat coral"><b>${rows.filter(([,v])=>v.qty===0).length}</b><span>Out of stock</span></div></div><div class="toolbar"><label class="search">${icon('search')} <input id="inventory-search" placeholder="Search your kitchen…"></label>${['all','Fridge','Freezer','Pantry'].map((x,i)=>`<button class="filter ${i?'':'active'}" data-location="${x}">${x==='all'?'All':x}</button>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>Ingredient</th><th>Status</th><th>Quantity</th><th>Location</th><th>Category</th></tr></thead><tbody id="inventory-body">${invRows(rows)}</tbody></table></div>`}
function plannerView(){
 const dates=currentWeek(parseDate(plannerMonday));
 $('#planner-view').innerHTML=`<div class="page-head"><div><p class="eyebrow">${weekLabel(dates)}</p><h1>Make a date.</h1><p>Plan ahead. Look back. Keep something good on the menu.</p></div><button class="primary-btn" data-action="plan-meal">＋ Plan a meal</button></div><div class="week-navigation"><button class="secondary-btn" data-week="-1" aria-label="Previous week">← Previous week</button><button class="secondary-btn" data-week="today">This week</button><button class="secondary-btn" data-week="1" aria-label="Next week">Next week →</button></div><div class="week-grid">${dates.map((date,index)=>{const key=dateKey(date),day=weekdays[index];return `<section class="day-column"><div class="day-title"><b>${day.slice(0,3)}</b><span>${date.getDate()}</span></div>${plans.filter(p=>p.date===key&&recipes.some(r=>r.id===p.recipe)).map(p=>{const r=recipes.find(r=>r.id===p.recipe);return `<article class="planned-card" data-recipe="${escapeHtml(r.id)}"><span>${escapeHtml(p.slot)}</span><div class="meal-emoji">${icon('utensils')}</div><strong>${escapeHtml(r.name)}</strong><small>${p.servings} servings · ${r.time} min</small><button data-start="${escapeHtml(r.id)}" data-servings="${p.servings}">Start cooking</button><button class="plan-edit" data-edit-plan="${escapeHtml(p.id)}">Edit meal</button></article>`}).join('')}<button class="add-slot" data-day="${day}">＋ Add meal</button></section>`}).join('')}</div>`;
}
function shopRow(item,index){const sources=sourceRecipes(item,recipes);return `<div class="shop-row ${item.checked?'checked':''}"><label class="shop-check"><input type="checkbox" data-shop="${index}" aria-label="Mark ${escapeHtml(item.name)} ${item.checked?'not purchased':'purchased'}" ${item.checked?'checked':''}><span class="checkmark" aria-hidden="true">✓</span></label><div class="shop-item"><strong>${escapeHtml(item.name)}</strong>${showShoppingSources?`<span class="shopping-sources"><small>For:</small>${sources.map(recipe=>`<button type="button" class="recipe-source" data-preview-recipe="${escapeHtml(recipe.id)}">${escapeHtml(recipe.name)}</button>`).join('')}</span>`:''}</div><b>${escapeHtml(quantityLabel(item.qty,item.unit))}</b></div>`}
function previewRecipe(id){
 const recipe=recipes.find(r=>r.id===id);if(!recipe)return;
 let dialog=$('#recipe-peek');if(!dialog){dialog=document.createElement('dialog');dialog.id='recipe-peek';dialog.className='recipe-peek';document.body.append(dialog)}
 dialog.innerHTML=`<div class="peek-heading"><div><p class="eyebrow">FROM YOUR COOKBOOK</p><h2>${escapeHtml(recipe.name)}</h2></div><button class="round-btn" aria-label="Close recipe preview">×</button></div>${recipe.imageUrl?`<img class="peek-cover" src="${escapeHtml(recipe.imageUrl)}" alt="${escapeHtml(recipe.name)}">`:''}<p>${recipe.time} min · ${escapeHtml(recipe.difficulty)} · ${recipe.servings} servings</p><h3>Ingredients</h3><ul>${recipe.ingredients.map(([name,qty,unit,note])=>`<li><strong>${escapeHtml(name)}</strong> · ${escapeHtml(quantityLabel(qty,unit))}${note?` — ${escapeHtml(note)}`:''}</li>`).join('')}</ul><h3>Method</h3><ol>${recipe.steps.map(step=>`<li>${escapeHtml(step)}</li>`).join('')}</ol><button class="primary-btn peek-open">Open full recipe ↗</button>`;
 dialog.querySelector('.round-btn').onclick=()=>dialog.close();dialog.querySelector('.peek-open').onclick=()=>{dialog.close();detail(id)};
 dialog.onclick=event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close()}};
 if(!dialog.open)dialog.showModal();
}

function shoppingView(){const active=shopping.filter(item=>!item.checked),done=shopping.filter(item=>item.checked);$('#shopping-view').innerHTML=`<div class="page-head"><div><p class="eyebrow">SMART LIST</p><h1>Shopping</h1><p>${active.length} items left · grouped for an easier shop</p></div><button class="primary-btn" data-action="manual-item">＋ Add item</button></div><div class="shopping-options"><label><input type="checkbox" data-show-sources ${showShoppingSources?'checked':''}> Show recipe labels</label></div><div class="shopping-layout"><div class="shopping-card"><div class="shop-progress"><span><b>${done.length}</b> of ${shopping.length} picked up</span><div><i style="width:${shopping.length?done.length/shopping.length*100:0}%"></i></div></div>${[...new Set(active.map(item=>categories[item.name]||'Other'))].map(category=>`<div class="shop-group"><h3>${escapeHtml(category)}</h3>${shopping.map((item,index)=>!item.checked&&(categories[item.name]||'Other')===category?shopRow(item,index):'').join('')}</div>`).join('')}${done.length?`<div class="shop-group complete"><h3>Completed</h3>${shopping.map((item,index)=>item.checked?shopRow(item,index):'').join('')}</div>`:''}<button class="clear-btn" data-action="clear-completed">Clear completed</button></div><aside class="shop-aside"><p class="eyebrow">YOUR SHOPPING, YOUR CALL</p><h2>A little top-up.</h2><p>Choose what you want to buy when planning a meal. Recipe labels keep track of what it is for; hiding or clearing a label never changes your quantities.</p></aside></div>`}

function ingredientRows(r,s=r.servings){return checks(r,s).map(row=>`<div class="ingredient-row"><span class="availability ${row.status}">${row.status==='ready'?'✓':row.status==='low'?'!':row.status==='partial'?'◐':'×'}</span><span><strong>${escapeHtml(row.name)}</strong><small>${escapeHtml(row.note||categories[row.name]||'')}</small></span><b>${escapeHtml(quantityLabel(row.need,row.unit))}</b><small class="have">${row.isFlexible?(row.item?.qty>0?'In your inventory · use as you like':'Not in inventory'):!row.compatible&&row.item?'Check inventory unit':row.missing?`Have ${fmt(row.have)} · Missing ${fmt(row.missing)}`:`Have ${fmt(row.have)}`}</small></div>`).join('')}

function detail(id){let r=recipes.find(x=>x.id===id);currentRecipe=r;$('#detail-view').innerHTML=`<button class="back-btn" data-view="recipes">← Back to recipes</button><div class="detail-hero"><div class="detail-image" style="background:${r.bg}">${recipeVisual(r)}</div><div><span class="tag">${r.tags[0]||r.cuisine}</span><h1>${r.name}</h1><p class="detail-copy">One for the regular rotation.</p><div class="facts"><span><b>${r.time}</b> min total</span>${r.prep?`<span><b>${r.prep}</b> min prep</span>`:''}${r.cook?`<span><b>${r.cook}</b> min cook</span>`:''}<span><b>${r.difficulty}</b> difficulty</span><span><b>★ ${r.rating}</b> your rating</span></div><div class="detail-actions"><button class="primary-btn" data-start="${r.id}">Start cooking</button><button class="secondary-btn" data-plan="${r.id}">＋ Add to meal plan</button><button class="secondary-btn" data-edit-recipe="${escapeHtml(r.id)}">Edit recipe</button><button class="clear-btn" data-delete-recipe="${escapeHtml(r.id)}">Delete recipe</button></div></div></div><div class="detail-grid"><section class="panel"><div class="section-heading"><div><p class="eyebrow">WHAT YOU'LL NEED</p><h2>Ingredients</h2></div><label class="servings">Servings <input type="number" id="servings" min="1" value="${r.servings}"></label></div><div id="ingredient-checks">${ingredientRows(r)}</div></section><section class="panel instructions"><p class="eyebrow">METHOD</p><h2>Directions</h2>${r.steps.map((s,i)=>`<div class="instruction"><b>${i+1}</b><p>${s}</p></div>`).join('')}</section></div>`;show('detail')}
function cooking(id,servings){currentRecipe=recipes.find(x=>x.id===id);if(!currentRecipe)return;let selected=$('#detail-view.active #servings')?.value;cookingServings=Number(servings||selected||currentRecipe.servings);if(!Number.isFinite(cookingServings)||cookingServings<1)return toast('Choose at least one serving');cookStep=0;renderCook()}
function renderCook(){let r=currentRecipe;if(cookStep>=r.steps.length)return reconcile();$('#cooking-view').innerHTML=`<div class="cook-top"><button data-action="exit-cook">× Exit</button><span>Cooking mode</span><span>${cookStep+1} / ${r.steps.length}</span></div><div class="cook-body"><aside><div class="cook-art" style="background:${r.bg}">${recipeVisual(r)}</div><p class="eyebrow">INGREDIENTS</p>${r.ingredients.map(([n,q,u])=>`<div class="cook-ingredient"><span>○</span><b>${n}</b><em>${escapeHtml(quantityLabel(q,u,cookingServings/r.servings))}</em></div>`).join('')}</aside><section><div class="progress"><i style="width:${(cookStep+1)/r.steps.length*100}%"></i></div><p class="eyebrow">STEP ${cookStep+1} OF ${r.steps.length}</p><h1>${r.steps[cookStep]}</h1><p class="cook-tip">Take your time. You can move back if you need another look.</p><div class="cook-nav"><button class="secondary-btn" data-action="prev-step" ${cookStep===0?'disabled':''}>← Previous</button><button class="primary-btn" data-action="next-step">${cookStep===r.steps.length-1?'Finish cooking':'Next step →'}</button></div></section></div>`;show('cooking')}
function reconcile(){let r=currentRecipe;$('#cooking-view').innerHTML=`<div class="reconcile"><p class="eyebrow">DINNER IS READY</p><h1>Update your inventory</h1><p>Review amounts for ${cookingServings} servings. Nothing changes until you confirm.</p><div class="panel reconcile-list">${checks(r,cookingServings).map((x,index)=>{let update=remainingInventory(x);if(!update)return `<div><strong>${escapeHtml(x.name)}</strong><p>${x.isFlexible?'Amount is up to you. Stock stays unchanged; adjust it in Inventory if needed.':x.item?'Units cannot be compared. Update this ingredient in Inventory.':'Not in your inventory. No stock will be changed.'}</p></div>`;return `<label><span><strong>${escapeHtml(x.name)}</strong><small>${update.before} ${escapeHtml(update.unit)} before</small></span><span>→</span><input type="number" min="0" step="any" value="${update.after}" data-remaining="${index}"><b>${escapeHtml(update.unit)}</b></label>`}).join('')}</div><div class="detail-actions"><button class="primary-btn" data-action="confirm-deduction">Confirm updates</button><button class="secondary-btn" data-action="leave-unchanged">Leave unchanged</button></div></div>`}
async function confirmDeduction(button){
 if(button.disabled)return;
 const rows=checks(currentRecipe,cookingServings),updates=[];
 for(const input of $$('[data-remaining]')){
  const row=rows[Number(input.dataset.remaining)],qty=Number(input.value);
  if(!input.value.trim()||!Number.isFinite(qty)||qty<0)return toast('Enter a valid remaining quantity');
  if(row?.item&&row.compatible)updates.push({key:row.inventoryKey,item:{...row.item,qty}});
 }
 button.disabled=true;
 try{
  const results=await Promise.allSettled(updates.map(async update=>({key:update.key,item:await upsertInventory(update.key,update.item)})));
  results.forEach(result=>{if(result.status==='fulfilled')inventory[result.value.key]=result.value.item});
  const failed=results.filter(result=>result.status==='rejected');
  if(failed.length){toast('Some updates failed. Saved amounts are kept; review before retrying.');return}
  show('home');toast('Inventory updated');
 }catch(error){toast(`Inventory update failed: ${error.message}`)}finally{button.disabled=false}
}
function modal(title,body,action='Save'){$('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h2>${title}</h2><button data-action="close-modal">×</button></div><form id="modal-form">${body}<div class="modal-actions"><button type="button" class="secondary-btn" data-action="close-modal">Cancel</button><button class="primary-btn">${action}</button></div></form></div></div>`}
function planModal(id,day='Monday',planId=null){
 const existing=planId===null?null:plans.find(p=>String(p.id)===String(planId));
 if(planId!==null&&!existing)return toast('This meal is no longer in your plan');
 const recipe=recipes.find(r=>r.id===(existing?.recipe||id))||recipes[0];if(!recipe)return toast('Add a recipe first');
 const date=existing?.date||dateForDay(day,plannerMonday),slot=existing?.slot||'Dinner';
 modal(existing?'Edit planned meal':'Plan a meal',`${existing?`<input type="hidden" name="plan-id" value="${escapeHtml(existing.id)}">`:''}<label>Recipe<select name="recipe">${recipes.map(r=>`<option value="${escapeHtml(r.id)}" ${r.id===recipe.id?'selected':''}>${escapeHtml(r.name)}</option>`).join('')}</select></label><div class="form-grid"><label>Date<input type="date" name="date" required value="${date}"></label><label>Meal<select name="slot">${['Breakfast','Brunch','Lunch','Dinner','Snack'].map(value=>`<option ${value===slot?'selected':''}>${value}</option>`).join('')}</select></label></div><label>Servings<input name="servings" type="number" min="1" step="1" required value="${existing?.servings||recipe.servings}"></label><div id="plan-missing-review"></div>${existing?`<button type="button" class="clear-btn" data-remove-plan="${escapeHtml(existing.id)}">Remove meal</button>`:''}`,existing?'Save changes':'Add to meal plan');
 document.querySelector('.modal').classList.add('plan-modal');refreshPlanMissing();
}
function refreshPlanMissing(){
 const form=$('#modal-form'),review=$('#plan-missing-review');if(!review)return;
 const recipe=recipes.find(r=>r.id===form.elements.recipe.value),servings=Number(form.elements.servings.value);
 if(!recipe||!Number.isInteger(servings)||servings<1){review.textContent='Choose at least one whole serving.';return}
 if(form._reviewRecipe!==recipe.id){form._reviewRecipe=recipe.id;form._purchaseOverrides=new Map()}
 const rows=checks(recipe,servings);
 const rowMarkup=(row,index)=>{const key=row.ingredientId||row.name,coverage=cartCoverage(row,shopping),onList=row.isFlexible?shopping.some(item=>cartMatches(row,item)):coverage>0,checked=form._purchaseOverrides.has(key)?form._purchaseOverrides.get(key):needsPurchase(row);return `<label class="purchase-row ${onList?'already-shopping':''}"><input type="checkbox" name="missing" value="${index}" data-purchase-key="${escapeHtml(key)}" ${checked?'checked':''}><span><strong>${escapeHtml(row.name)}</strong><small>${row.isFlexible?`${escapeHtml(quantityLabel(null,row.unit))} · ${needsPurchase(row)?'Not in inventory':'In your inventory'}`:row.missing>0?`Need ${fmt(row.missing)} ${escapeHtml(row.unit)} more`:`Have ${fmt(row.have)} ${escapeHtml(row.unit)} · Need ${fmt(row.need)}`}${row.compatible===false?' · Check inventory unit':''}</small>${onList?`<span class="on-list">On shopping list${row.isFlexible?'':` · ${fmt(coverage)} ${escapeHtml(row.unit)}`}</span>`:''}</span></label>`};
 review.innerHTML=`<p class="purchase-intro">Missing ingredients start checked. Change any selection in either list.</p><div class="purchase-columns"><section><h3>Missing <span>${rows.filter(needsPurchase).length}</span></h3>${rows.map((row,index)=>needsPurchase(row)?rowMarkup(row,index):'').join('')||'<p>Nothing missing. Lovely.</p>'}</section><section><h3>Already have <span>${rows.filter(row=>!needsPurchase(row)).length}</span></h3>${rows.map((row,index)=>!needsPurchase(row)?rowMarkup(row,index):'').join('')||'<p>No stocked ingredients for this recipe yet.</p>'}</section></div><button type="button" class="secondary-btn add-plan-shopping" data-action="add-plan-shopping">Add missing items to shopping list</button><p id="plan-shopping-status" role="status"></p>`;
}
function addPlanShopping(){
 const form=$('#modal-form'),data=new FormData(form),recipe=recipes.find(r=>r.id===data.get('recipe')),servings=Number(data.get('servings'));
 if(!recipe||!Number.isInteger(servings)||servings<1)return toast('Choose a recipe and at least one whole serving');
 if(!data.getAll('missing').length){$('#plan-shopping-status').textContent='Select an ingredient to add to shopping.';return}
 const before=shopping;shopping=addSelectedIngredients(shopping,checks(recipe,servings),data.getAll('missing'),recipe,recipes);
 if(!saveState()){shopping=before;return}
 refreshPlanMissing();$('#plan-shopping-status').textContent='Selected items are on your shopping list. Existing amounts were topped up only where needed.';
}
function savePlannedMeal(data){
 const recipe=recipes.find(r=>r.id===data.get('recipe')),servings=Number(data.get('servings'));
 const date=data.get('date')||dateForDay(data.get('day'),plannerMonday),parsed=parseDate(date),day=weekdays[(parsed.getDay()+6)%7],slot=data.get('slot'),planId=data.get('plan-id');
 if(!recipe||!Number.isInteger(servings)||servings<1)throw new Error('Choose a recipe and at least one whole serving.');
 if(!['Breakfast','Brunch','Lunch','Dinner','Snack'].includes(slot))throw new Error('Choose a valid meal.');
 const index=planId===null?-1:plans.findIndex(p=>String(p.id)===planId);if(planId!==null&&index<0)throw new Error('This meal is no longer in your plan.');
 const oldPlans=plans,oldShopping=shopping;plans=plans.map(p=>({...p}));
 const meal={id:index<0?crypto.randomUUID():plans[index].id,date,day,slot,servings,recipe:recipe.id};
 if(index<0)plans.push(meal);else{const previous=plans[index].recipe;plans[index]=meal;if(previous!==recipe.id&&!plans.some(p=>p.recipe===previous))shopping=detachRecipeSources(shopping,previous,recipes)}
 shopping=addSelectedIngredients(shopping,checks(recipe,servings),data.getAll('missing'),recipe,recipes);
 if(!saveState()){plans=oldPlans;shopping=oldShopping;throw new Error('Meal changes could not be saved. Try again.');}
 plannerMonday=dateKey(currentWeek(parsed)[0]);return index<0?'Meal planned':'Planned meal updated';
}
function removePlannedMeal(id){
 const before=plans,previousShopping=shopping,removed=plans.find(p=>String(p.id)===String(id));plans=plans.filter(p=>String(p.id)!==String(id));
 if(removed&&!plans.some(p=>p.recipe===removed.recipe))shopping=detachRecipeSources(shopping,removed.recipe,recipes);
 if(!saveState()){plans=before;shopping=previousShopping;throw new Error('Meal could not be removed. Try again.');}
}

const recipeUnits=[...units,'as needed','to taste'];
function ingredientInputRow(){return `<div class="recipe-ingredient-input">${ingredientPicker("ingredient-name",false)}<input name="ingredient-quantity" type="number" min="0.01" step="any" placeholder="Optional qty" aria-label="Quantity (optional)"><select name="ingredient-unit">${recipeUnits.map(x=>`<option>${x}</option>`).join('')}</select><input name="ingredient-note" placeholder="Optional note"><button type="button" class="row-remove" data-action="remove-recipe-row" aria-label="Remove ingredient">×</button></div>`}
function instructionInputRow(){return `<div class="recipe-step-input"><b></b><textarea name="recipe-step" rows="2" required placeholder="Describe this step…"></textarea><button type="button" class="row-remove" data-action="remove-recipe-row" aria-label="Remove step">×</button></div>`}
function recipeModal(editId=null){let existing=editId?recipes.find(r=>r.id===editId):null;if(editId&&!existing)return toast('Recipe not found');let suggestions=[...new Set(recipes.flatMap(r=>[r.cuisine,...r.tags]).filter(Boolean))].sort();modal(existing?'Edit recipe':'Add recipe',`<div class="recipe-form"><section class="recipe-basics"><label class="cover-upload"><input name="cover" type="file" accept="image/jpeg,image/png,image/webp"><span class="cover-preview"><b>＋</b><strong>Add cover photo</strong><small>Optional · JPG, PNG or WebP</small></span></label><label class="recipe-name-label">Recipe name<input name="recipe-name" required autofocus placeholder="Recipe name"></label><div class="field-label">Tags <span>Press Enter or comma to add</span></div><div class="tag-editor" data-tag-editor><div class="tag-chips"></div><input data-tag-input placeholder="Korean, Japanese, Fusion…" list="recipe-tag-suggestions"></div><input type="hidden" name="recipe-tags"><datalist id="recipe-tag-suggestions">${suggestions.map(x=>`<option value="${escapeHtml(x)}">`).join('')}</datalist></section><section><p class="form-section-title">Time & details</p><div class="details-grid"><fieldset><legend>Difficulty</legend><div class="choice-chips">${['Easy','Medium','Hard'].map((x,i)=>`<label><input type="radio" name="difficulty" value="${x}" ${i?'':'checked'}><span>${x}</span></label>`).join('')}</div></fieldset><fieldset><legend>Servings</legend><div class="servings-stepper"><button type="button" data-servings="-" aria-label="Decrease servings">−</button><output>2</output><input name="servings" type="hidden" value="2"><button type="button" data-servings="+" aria-label="Increase servings">＋</button></div></fieldset></div><div class="time-grid"><label class="total-time">Total time<input name="total-time" type="number" min="0" required placeholder="35"><span>min</span></label><div class="optional-times"><span>Optional breakdown</span><label>Prep<input name="prep" type="number" min="0" placeholder="10"><i>min</i></label><label>Cook<input name="cook" type="number" min="0" placeholder="25"><i>min</i></label></div></div><p class="time-suggestion" aria-live="polite"></p></section><section><p class="form-section-title">Ingredients</p><p class="quantity-hint">Leave quantity blank for As needed, or choose To taste from the measurement menu.</p><div id="recipe-ingredient-inputs">${ingredientInputRow()}${ingredientInputRow()}</div><button type="button" class="add-row-btn" data-action="add-recipe-ingredient">＋ Add ingredient</button></section><section><p class="form-section-title">Instructions</p><div id="recipe-step-inputs">${instructionInputRow()}${instructionInputRow()}</div><button type="button" class="add-row-btn" data-action="add-recipe-step">＋ Add step</button></section><section><p class="form-section-title">Source</p><label>Source <span class="optional">Optional</span><input name="source" placeholder="Recipe website, TikTok, Instagram, cookbook, etc."></label></section></div>`,'Save recipe');document.querySelector('.modal')?.classList.add('recipe-modal');if(existing)populateRecipeEditor(existing)}
function populateRecipeEditor(recipe){
 const form=$('#modal-form');
 const id=document.createElement('input');id.type='hidden';id.name='edit-recipe-id';id.value=recipe.id;form.append(id);
 for(const [name,value] of Object.entries({'recipe-name':recipe.name,'total-time':recipe.time,prep:recipe.prep||'',cook:recipe.cook||'',source:recipe.source,servings:recipe.servings}))form.elements[name].value=value;
 form.elements['total-time'].dataset.manual='true';
 form.querySelector('.servings-stepper output').textContent=recipe.servings;
 const difficulty=[...form.querySelectorAll('[name="difficulty"]')].find(input=>input.value===recipe.difficulty);if(difficulty)difficulty.checked=true;
 recipe.tags.forEach(addRecipeTag);
 const ingredients=$('#recipe-ingredient-inputs');ingredients.innerHTML=recipe.ingredients.map(()=>ingredientInputRow()).join('');
 [...ingredients.children].forEach((row,i)=>{
  const [name,quantity,unit,note,ingredientId]=recipe.ingredients[i];
  presetIngredient(row.querySelector('.ingredient-picker'),{id:ingredientId,canonical_name:name,default_unit:unit});
  row.querySelector('[name="ingredient-quantity"]').value=quantity??'';row.querySelector('[name="ingredient-quantity"]').disabled=['as needed','to taste'].includes(unit);
  row.querySelector('[name="ingredient-note"]').value=note||'';
 });
 const steps=$('#recipe-step-inputs');steps.innerHTML=recipe.steps.map(()=>instructionInputRow()).join('');
 [...steps.querySelectorAll('textarea')].forEach((input,i)=>input.value=recipe.steps[i]);
 if(recipe.imageUrl){const preview=form.querySelector('.cover-preview');preview.style.backgroundImage=`url(${JSON.stringify(recipe.imageUrl)})`;preview.classList.add('has-image');preview.querySelector('strong').textContent='Change cover photo'}
 form.elements['recipe-name'].focus();
}

function show(v){$$('.view').forEach(x=>x.classList.remove('active'));$('#'+v+'-view').classList.add('active');$$('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.view===v));scrollTo(0,0);if(v==='home')home();if(v==='recipes')recipesView();if(v==='inventory')inventoryView();if(v==='catalogue')catalogueView();if(v==='planner')plannerView();if(v==='shopping')shoppingView();if(v==='profile'){window.miseProfileStats={recipes:recipes.length,ingredients:Object.keys(inventory).length};window.dispatchEvent(new CustomEvent('mise-profile-open'))}}
function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),1800)}
function addShop(name,qty,unit,sources=[]){let x=shopping.find(i=>i.name===name&&!i.checked&&i.unit===unit);if(x){x.qty+=qty;x.sources=[...new Set([...x.sources,...sources])]}else shopping.push({name,qty,unit,checked:false,sources})}
document.addEventListener('click',async e=>{let peek=e.target.closest('[data-preview-recipe]');if(peek)return previewRecipe(peek.dataset.previewRecipe);let nav=e.target.closest('[data-view]');if(nav)return show(nav.dataset.view);let rc=e.target.closest('[data-recipe]');if(rc&&!e.target.closest('button'))return detail(rc.dataset.recipe);let openRecipe=e.target.closest('[data-open-recipe]');if(openRecipe)return detail(openRecipe.dataset.openRecipe);let start=e.target.closest('[data-start]');if(start)return cooking(start.dataset.start,start.dataset.servings);let recipeEdit=e.target.closest('[data-edit-recipe]');if(recipeEdit)return recipeModal(recipeEdit.dataset.editRecipe);let recipeDelete=e.target.closest('[data-delete-recipe]');if(recipeDelete){const recipe=recipes.find(r=>r.id===recipeDelete.dataset.deleteRecipe);if(!recipe)return;modal('Delete recipe?',`<p>Delete <strong>${escapeHtml(recipe.name)}</strong> and remove it from your meal plan? This cannot be undone. Your inventory and shopping quantities stay as they are.</p><input type="hidden" name="delete-recipe-id" value="${escapeHtml(recipe.id)}">`,'Delete recipe');return}let week=e.target.closest('[data-week]');if(week){plannerMonday=week.dataset.week==='today'?dateKey(currentWeek()[0]):shiftWeek(plannerMonday,Number(week.dataset.week));return plannerView()}let edit=e.target.closest('[data-edit-plan]');if(edit)return planModal(null,'Monday',edit.dataset.editPlan);let remove=e.target.closest('[data-remove-plan]');if(remove){modal('Remove planned meal?',`<p>This removes the meal from your weekly plan. Your shopping quantities stay as they are. Recipe labels clear when this is its last planned meal.</p><input type="hidden" name="remove-plan-id" value="${escapeHtml(remove.dataset.removePlan)}">`,'Remove meal');return}let plan=e.target.closest('[data-plan]');if(plan)return planModal(plan.dataset.plan);let q=e.target.closest('[data-qty]');if(q){let name=q.dataset.name,x=inventory[name],before=x.qty,d=['g','ml'].includes(x.unit)?50:1;x.qty=Math.max(0,x.qty+(q.dataset.qty==='+'?d:-d));inventoryView();home();try{inventory[name]=await upsertInventory(name,x);toast('Inventory updated')}catch(error){x.qty=before;inventoryView();home();toast(`Inventory update failed: ${error.message}`)}return}let day=e.target.closest('[data-day]');if(day)return recipes.length?planModal(recipes[0].id,day.dataset.day):toast('Add a recipe first');let a=e.target.closest('[data-action]')?.dataset.action;if(a==='add-plan-shopping')return addPlanShopping();if(a==='cook-now'){show('recipes');setTimeout(()=>document.querySelector('[data-filter="ready"]')?.click(),0)}if(a==='add-low'){Object.entries(inventory).filter(([,v])=>v.qty<=v.threshold).forEach(([n,v])=>addShop(n,Math.max(v.threshold-v.qty,['g','ml'].includes(v.unit)?100:1),v.unit));saveState();toast('Low-stock items added')}if(a==='plan-meal'){if(recipes.length)planModal(recipes[0].id);else toast('Add a recipe first')}if(a==='manual-item')modal('Add shopping item','<label>Item<input name="item" required placeholder="e.g. Lemons"></label><div class="form-grid"><label>Quantity<input name="qty" type="number" min="0.1" step="0.1" value="1"></label><label>Unit<select name="unit"><option>pcs</option><option>g</option><option>ml</option><option>pack</option></select></label></div>','Add item');if(a==='add-inventory')modal('Add ingredient',`${ingredientPicker('ingredient')}<div class="form-grid"><label>Quantity<input name="qty" type="number" min="0" step="any" required value="1"></label><label>Unit<select name="unit">${units.map(x=>`<option>${x}</option>`).join('')}</select></label></div><div class="form-grid"><label>Location<select name="location"><option>Fridge</option><option>Freezer</option><option>Pantry</option></select></label><label>Low-stock at<input name="threshold" type="number" min="0" step="any" required value="1"></label></div>`);if(a==='add-recipe')recipeModal();if(a==='clear-completed'){shopping=shopping.filter(x=>!x.checked);saveState();shoppingView();toast('Completed items cleared')}if(a==='close-modal')$('#modal-root').innerHTML='';if(a==='next-step'){cookStep++;renderCook()}if(a==='prev-step'){cookStep=Math.max(0,cookStep-1);renderCook()}if(a==='exit-cook')detail(currentRecipe.id);if(a==='confirm-deduction')await confirmDeduction(e.target.closest('button'));if(a==='leave-unchanged')show('home')});
document.addEventListener('change',e=>{if(e.target.matches('[data-show-sources]')){showShoppingSources=e.target.checked;try{if(activeUserId)localStorage.setItem('mise-meal-sources-'+activeUserId,String(showShoppingSources))}catch(error){console.warn(error)}shoppingView();return}if(e.target.matches('[data-purchase-key]')){const form=$('#modal-form');form._purchaseOverrides.set(e.target.dataset.purchaseKey,e.target.checked)}if(e.target.matches('[data-shop]')){shopping[Number(e.target.dataset.shop)].checked=e.target.checked;saveState();shoppingView()}if(e.target.id==='servings')$('#ingredient-checks').innerHTML=ingredientRows(currentRecipe,+e.target.value)});
document.addEventListener('input',e=>{if(e.target.id==='recipe-search'){let q=e.target.value.toLowerCase();$('#all-recipes').innerHTML=recipes.filter(r=>r.name.toLowerCase().includes(q)||r.ingredients.some(i=>i[0].toLowerCase().includes(q))).map(card).join('')}if(e.target.id==='inventory-search')$('#inventory-body').innerHTML=invRows(Object.entries(inventory).filter(([n])=>n.toLowerCase().includes(e.target.value.toLowerCase()))) });
function syncRecipeTags(){let hidden=document.querySelector('[name="recipe-tags"]');if(hidden)hidden.value=$$('.tag-chip').map(x=>x.dataset.tag).join('|')}
function addRecipeTag(value){let tag=value.trim().replace(/^,+|,+$/g,'');if(!tag||$$('.tag-chip').some(x=>x.dataset.tag.toLowerCase()===tag.toLowerCase()))return;let chip=document.createElement('span');chip.className='tag-chip';chip.dataset.tag=tag;chip.innerHTML=`${escapeHtml(tag)}<button type="button" aria-label="Remove ${escapeHtml(tag)}">×</button>`;document.querySelector('.tag-chips')?.append(chip);syncRecipeTags()}
document.addEventListener('keydown',e=>{if(!e.target.matches('[data-tag-input]')||(!['Enter',','].includes(e.key)))return;e.preventDefault();addRecipeTag(e.target.value);e.target.value=''})
document.addEventListener('blur',e=>{if(e.target.matches('[data-tag-input]')&&e.target.value.trim()){addRecipeTag(e.target.value);e.target.value=''}},true)
document.addEventListener('input',e=>{if(e.target.matches('[name="prep"],[name="cook"]')){let prep=document.querySelector('[name="prep"]'),cook=document.querySelector('[name="cook"]'),total=document.querySelector('[name="total-time"]'),note=document.querySelector('.time-suggestion');if(prep?.value!==''&&cook?.value!==''){let sum=+prep.value + +cook.value;note.textContent=`Prep + cook = ${sum} min`;if(!total.dataset.manual)total.value=sum}}if(e.target.matches('[name="total-time"]')&&e.isTrusted)e.target.dataset.manual='true'})
document.addEventListener('change',e=>{if(e.target.matches('[name="cover"]')&&e.target.files[0]){let preview=document.querySelector('.cover-preview');preview.style.backgroundImage=`url("${URL.createObjectURL(e.target.files[0])}")`;preview.classList.add('has-image');preview.querySelector('strong').textContent='Change cover photo'}})
document.addEventListener('click',e=>{let tagRemove=e.target.closest('.tag-chip button');if(tagRemove){tagRemove.parentElement.remove();syncRecipeTags();return}let servings=e.target.closest('[data-servings]');if(servings){let input=document.querySelector('[name="servings"]'),output=document.querySelector('.servings-stepper output'),next=Math.max(1,+input.value+(servings.dataset.servings==='+'?1:-1));input.value=next;output.textContent=next;return}let action=e.target.closest('[data-action]')?.dataset.action;if(action==='add-recipe-ingredient')document.querySelector('#recipe-ingredient-inputs')?.insertAdjacentHTML('beforeend',ingredientInputRow());if(action==='add-recipe-step')document.querySelector('#recipe-step-inputs')?.insertAdjacentHTML('beforeend',instructionInputRow());if(action==='remove-recipe-row'){let row=e.target.closest('.recipe-ingredient-input,.recipe-step-input'),container=row?.parentElement;if(container?.children.length>1)row.remove();else row.querySelectorAll('input,textarea').forEach(x=>x.value='')}})
document.addEventListener('submit',async e=>{if(e.target.id!=='modal-form')return;e.preventDefault();let form=e.target,button=form.querySelector('.primary-btn'),d=new FormData(form),view=null,message='Saved';button.disabled=true;try{if(d.has('delete-recipe-id')){await deleteRecipe(d.get('delete-recipe-id'));if(form.isConnected)$('#modal-root').innerHTML='';return}if(d.has('remove-plan-id')){removePlannedMeal(d.get('remove-plan-id'));view='planner';message='Meal removed'}else if(d.has('recipe')){message=savePlannedMeal(d);view='planner'}else if(d.has('item')){addShop(d.get('item').trim(),+d.get('qty'),d.get('unit'));view='shopping';message='Shopping item saved'}else if(d.has('ingredient')){let ingredient=selectedIngredient(form.querySelector('.ingredient-picker')),n=ingredient.canonical_name,item={ingredientId:ingredient.id,qty:+d.get('qty'),unit:d.get('unit'),threshold:+d.get('threshold'),location:d.get('location')};categories[n]=ingredient.category||'Other';inventory[n]=await upsertInventory(n,item);view='inventory';message='Ingredient saved'}else if(d.has('recipe-name')){let version=sessionVersion,existing=d.has('edit-recipe-id')?recipes.find(r=>r.id===d.get('edit-recipe-id')):null;if(d.has('edit-recipe-id')&&!existing)throw new Error('Recipe no longer exists.');let quantities=[...form.querySelectorAll('[name="ingredient-quantity"]')].map(input=>input.value),units=d.getAll('ingredient-unit'),notes=d.getAll('ingredient-note'),ingredients=[...form.querySelectorAll('.recipe-ingredient-input')].map((row,i)=>{if(!row.querySelector('.ingredient-picker>input').value.trim()&&!quantities[i].trim()&&!notes[i].trim())return null;let ingredient=selectedIngredient(row.querySelector('.ingredient-picker'));return[ingredient.canonical_name,parseRecipeQuantity(quantities[i],units[i]),units[i],notes[i].trim(),ingredient.id]}).filter(Boolean),steps=d.getAll('recipe-step').map(x=>x.trim()).filter(Boolean),tags=(d.get('recipe-tags')||'').split('|').filter(Boolean);if(!ingredients.length||!steps.length){toast('Add at least one ingredient and instruction step');button.disabled=false;return}if(new Set(ingredients.map(x=>x[4])).size!==ingredients.length)throw new Error('Each ingredient can appear once per recipe. Combine duplicate rows.');let prep=d.get('prep')===''?null:+d.get('prep'),cook=d.get('cook')===''?null:+d.get('cook'),record={name:d.get('recipe-name').trim(),cuisine:tags[0]||'Other',tags,prep,cook,time:+d.get('total-time'),difficulty:d.get('difficulty'),rating:existing?.rating||0,emoji:existing?.emoji||'🍽️',bg:existing?.bg||'#dce8df',imageUrl:existing?.imageUrl||'',servings:+d.get('servings'),source:d.get('source').trim(),ingredients,steps};ingredients.forEach(([name])=>{if(!categories[name])categories[name]='Other'});let saved=existing?await updateRecipe(existing.id,record,d.get('cover')):await createRecipe(record,d.get('cover'));if(version!==sessionVersion)return;if(existing)recipes=recipes.map(r=>r.id===existing.id?saved:r);else recipes.push(saved);shopping=shopping.map(item=>cleanRecipeSources(item,recipes));view='recipes';message=existing?'Recipe updated':'Recipe saved'}if(!d.has('recipe')&&!d.has('remove-plan-id'))saveState();$('#modal-root').innerHTML='';home();if(view)show(view);toast(message)}catch(error){console.error(error);button.disabled=false;toast(`Save failed: ${error.message}`)}});
document.addEventListener('click',e=>{let f=e.target.closest('[data-filter]');if(f){$$('[data-filter]').forEach(x=>x.classList.remove('active'));f.classList.add('active');let rs=f.dataset.filter==='ready'?recipes.filter(r=>!availability(r)):f.dataset.filter==='Easy'?recipes.filter(r=>r.difficulty==='Easy'):recipes;$('#all-recipes').innerHTML=rs.map(card).join('')}let l=e.target.closest('[data-location]');if(l){$$('[data-location]').forEach(x=>x.classList.remove('active'));l.classList.add('active');$$('[data-location-row]').forEach(x=>x.hidden=l.dataset.location!=='all'&&x.dataset.locationRow!==l.dataset.location)}});
renderIcons();
home();
function handleDatabaseLoad(session){return loadDatabase(session)}
window.addEventListener('mise-auth-change',event=>handleDatabaseLoad(event.detail.session));
supabase.auth.getSession().then(({data,error})=>{if(error)toast(`Could not restore kitchen: ${error.message}`);else handleDatabaseLoad(data.session)});

// Refresh calendar labels when returning after a day or week boundary.
document.addEventListener('visibilitychange',()=>{if(document.hidden)return;home();if(document.querySelector('#planner-view.active'))plannerView()});

document.addEventListener('input',event=>{if(event.target.matches('#modal-form [name="servings"]'))refreshPlanMissing()});
document.addEventListener('change',event=>{if(event.target.matches('#modal-form [name="recipe"]'))refreshPlanMissing()});

window.addEventListener('mise-catalogue-updated',()=>{loadedUserId=null;if(activeUserId)handleDatabaseLoad({user:{id:activeUserId}})});

document.addEventListener('keydown',event=>{const card=event.target.closest('.recipe-card');if(card&&event.target===card&&['Enter',' '].includes(event.key)){event.preventDefault();detail(card.dataset.recipe)}});

document.addEventListener('change',event=>{if(event.target.matches('[name="ingredient-unit"]')){const row=event.target.closest('.recipe-ingredient-input'),quantity=row.querySelector('[name="ingredient-quantity"]');quantity.disabled=['as needed','to taste'].includes(event.target.value);if(quantity.disabled)quantity.value=''}});
